from pathlib import Path
import json, html, urllib.parse, hashlib

ROOT=Path(r'E:/CRM Final Quisqueya Home noviembre')
OUT=ROOT/'08-diagramas-interactivos'
catalog=json.loads((OUT/'catalogo-diagramas.json').read_text(encoding='utf-8'))
drive=json.loads((ROOT/'00-fuentes-drive/2026-11-06/inventario-drive.json').read_text(encoding='utf-8'))['files']
sources={f['title']:{'local':'../00-fuentes-drive/2026-11-06/originales/'+urllib.parse.quote(f['relative_folder']+'/'+f['title'],safe='/'),'drive':f['url']} for f in drive}
receipts=[]
for d in catalog['diagrams']:
    folder=OUT/d['slug']
    valid=[]
    for p in folder.rglob('diagrama.finalize-summary.json'):
        j=json.loads(p.read_text(encoding='utf-8-sig'))
        if j.get('ok'):
            artifact=folder/'diagrama.html'
            sha=hashlib.sha256(artifact.read_bytes()).hexdigest()
            if j['artifact']['sha256']==sha:valid.append((p.stat().st_mtime,p,j))
    if not valid:raise RuntimeError('Sin receipt vigente '+d['slug'])
    _,p,j=max(valid)
    d['receipt']=p.relative_to(OUT).as_posix();d['browser']='pass';d['artifact_sha256']=j['artifact']['sha256']
    spec=json.loads((folder/'candidate.json').read_text(encoding='utf-8'))
    d['nodes']=[{'id':n['id'],'label':n['label'],'status':n.get('tag','objetivo propuesto')} for n in spec.get('components',spec.get('participants',spec.get('states',[])))]
    receipts.append({'diagram':d['slug'],'receipt':d['receipt'],'gates':j['gates'],'sha256':d['artifact_sha256'],'visualReview':j['visualReview']})
(OUT/'verificacion-paquete.json').write_text(json.dumps({'date':'2026-11-06','artifacts':receipts,'qa_scope':'Archify HTML checks; not CRM runtime or human architecture acceptance'},ensure_ascii=False,indent=2),encoding='utf-8')
data=json.dumps({'diagrams':catalog['diagrams'],'modules':catalog['modules'],'sources':sources},ensure_ascii=False).replace('</','<\\/')
